export function verifyRestoreDrill({manifest,restoredFiles=[],requiredKeys=[],checksums={}}={}){if(!manifest)return {ok:false,reason:'MANIFEST_REQUIRED'};const set=new Set(restoredFiles);const missing=requiredKeys.filter(k=>!set.has(k));const checksumFailures=[];for(const [k,expected] of Object.entries(manifest.checksums||{})){if(checksums[k]&&checksums[k]!==expected)checksumFailures.push(k)}return {ok:!missing.length&&!checksumFailures.length,missing,checksumFailures,verifiedAt:new Date().toISOString()}}
